import os
import torch
import torch.distributed as dist

def main():
    local_rank = int(os.environ["LOCAL_RANK"])
    if torch.cuda.is_available():
        device = torch.device("cuda", local_rank)
        torch.cuda.set_device(device)
        dist.init_process_group(backend="nccl", device_id=device)
    else:
        device = torch.device("cpu")
        dist.init_process_group(backend="gloo")

    try:
        print({
            "rank": dist.get_rank(),
            "world_size": dist.get_world_size(),
            "device": str(device),
        })
    finally:
        dist.destroy_process_group()

if __name__ == "__main__":
    main()

import torch.distributed as dist
from torch.nn.parallel import DistributedDataParallel as DDP
from torch.utils.data import DataLoader, DistributedSampler

def train_with_ddp(
    model, train_dataset, device, epochs, local_batch_size, train_step
):
    if not dist.is_initialized():
        raise RuntimeError("initialize the process group before constructing DDP")
    sampler = DistributedSampler(
        train_dataset, shuffle=True, seed=31, drop_last=False
    )  # May pad duplicate indices; record this choice.
    loader = DataLoader(
        train_dataset, batch_size=local_batch_size, sampler=sampler
    )
    ddp_kwargs = {"device_ids": [device.index]} if device.type == "cuda" else {}
    model = DDP(model.to(device), **ddp_kwargs)

    for epoch in range(epochs):
        sampler.set_epoch(epoch)
        for images, labels in loader:
            train_step(model, images.to(device), labels.to(device))
    return model

import torch.distributed as dist
from torch.distributed.device_mesh import init_device_mesh

def make_parallel_mesh(
    data_parallel_size, tensor_parallel_size, device_type="cuda"
):
    if device_type not in {"cpu", "cuda"}:
        raise ValueError("this lesson demonstrates CPU or CUDA DeviceMesh")
    if not dist.is_initialized():
        raise RuntimeError("launch every rank with torchrun before creating the mesh")
    mesh_world_size = data_parallel_size * tensor_parallel_size
    if mesh_world_size != dist.get_world_size():
        raise ValueError("mesh dimensions must multiply to world size")

    mesh = init_device_mesh(
        device_type,
        mesh_shape=(data_parallel_size, tensor_parallel_size),
        mesh_dim_names=("dp", "tp"),
    )
    return mesh, mesh["tp"], mesh["dp"]

import torch
import torch.distributed as dist

def reduce_accuracy(correct_local, examples_local, device):
    if not dist.is_initialized():
        raise RuntimeError("initialize the process group before reducing metrics")
    counts = torch.tensor(
        [correct_local, examples_local], device=device, dtype=torch.float64
    )
    dist.all_reduce(counts, op=dist.ReduceOp.SUM)
    examples = int(counts[1].item())
    if examples == 0:
        raise ValueError("global metric denominator is zero")
    result = {"accuracy": (counts[0] / counts[1]).item(), "examples": examples}
    if dist.get_rank() == 0:
        print(result)
    return result
